   ("Types of discontinuity", table(["Type", "What happens", "Example at $x=0$"], [["removable", "limit exists, value missing or different", "$\\frac{x^2-x}{x}$"], ["jump", "one-sided limits exist but differ", "$\\frac{|x|}{x}$, $\\lfloor x\\rfloor$ at integers"], ["infinite", "a one-sided limit is $\\pm\\infty$", "$\\frac{1}{x^2}$"], ["oscillating", "no one-sided limit", "$\\sin\\frac1x$"]])),
   ("Intermediate Value Theorem", ul(["If $f$ is continuous on $[a,b]$ and $N$ is between $f(a)$ and $f(b)$, then $f(c)=N$ for some $c\\in(a,b)$.", "Root finding: if $f(a)f(b)<0$ there is a root in $(a,b)$.", "Example: $x^3-15x+1$ has $f(-4)=-3$, $f(-1)=15$, $f(1)=-13$, $f(4)=5$: three sign changes, three roots in $[-4,4]$.", "Continuity on the whole closed interval is essential (a jump can skip the value)."])),
