   ("Rolle and the Mean Value Theorem", ul(["<b>Rolle</b>: continuous on $[a,b]$, differentiable on $(a,b)$, $f(a)=f(b)$ $\\Rightarrow$ $f'(c)=0$ somewhere.", "<b>MVT</b>: same hypotheses, no condition on endpoints $\\Rightarrow$ $f'(c)=\\frac{f(b)-f(a)}{b-a}$.", "A thermometer rising $-19\\to100$ °C in $14$ s was rising at exactly $8.5$ °C/s at some instant.", "$\\sqrt{x(1-x)}$ satisfies the MVT on $[0,1]$: differentiability is only needed on the open interval."])),
   ("Increasing, decreasing, concavity", table(["Test", "Conclusion"], [["$f'>0$ on an interval", "increasing"], ["$f'$ changes $+\\to-$ at $c$", "local maximum"], ["$f'$ changes $-\\to+$ at $c$", "local minimum"], ["$f''>0$", "concave up"], ["$f''$ changes sign at $c$", "inflection point"], ["$f'(c)=0$, $f''(c)>0$ ($<0$)", "local min (max)"]])),
